UPDATE sach SET mo_ta = 'Những kinh nghiệm nghề nghiệp cốt lõi để xây dựng phần mềm tốt và phát triển tư duy của một lập trình viên thực dụng. Cuốn sách bàn về trách nhiệm nghề nghiệp, giao tiếp trong nhóm, tự động hóa công việc và cách thích nghi khi yêu cầu thay đổi. Những gợi ý thực hành khuyến khích người đọc chủ động học hỏi, thử nghiệm và cải thiện chất lượng công việc mỗi ngày.' WHERE ma_sach = 'S003' AND ten_sach = 'The Pragmatic Programmer' AND (mo_ta = 'Những kinh nghiệm nghề nghiệp cốt lõi để xây dựng phần mềm tốt và phát triển tư duy của một lập trình viên thực dụng.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Giải thích nền tảng của hệ thống dữ liệu tin cậy, có khả năng mở rộng và dễ bảo trì. Nội dung kết nối các chủ đề lưu trữ, mô hình dữ liệu, sao chép, phân vùng, giao dịch và xử lý dữ liệu phân tán. Phù hợp với người đã có nền tảng lập trình và muốn hiểu các đánh đổi khi lựa chọn kiến trúc cho hệ thống có nhiều dữ liệu.' WHERE ma_sach = 'S004' AND ten_sach = 'Designing Data-Intensive Applications' AND (mo_ta = 'Giải thích nền tảng của hệ thống dữ liệu tin cậy, có khả năng mở rộng và dễ bảo trì.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Câu chuyện giàu tính biểu tượng về tình bạn, trách nhiệm và cách người lớn nhìn thế giới. Qua cuộc gặp gỡ giữa một phi công và hoàng tử nhỏ đến từ hành tinh xa xôi, tác phẩm gợi mở những suy nghĩ về sự cô đơn, tình yêu và điều làm nên một mối gắn bó. Lối kể nhẹ nhàng cùng hình ảnh giàu liên tưởng phù hợp để đọc chậm và suy ngẫm ở nhiều lứa tuổi.' WHERE ma_sach = 'S005' AND ten_sach = 'The Little Prince' AND (mo_ta = 'Câu chuyện giàu tính biểu tượng về tình bạn, trách nhiệm và cách người lớn nhìn thế giới.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Tiểu thuyết phản địa đàng về giám sát, tuyên truyền và quyền lực toàn trị. Nhân vật Winston Smith sống trong một xã hội nơi suy nghĩ, ngôn ngữ và ký ức đều chịu sự kiểm soát của quyền lực. Hành trình của anh đặt ra câu hỏi về tự do cá nhân, sự thật và khả năng giữ gìn bản sắc trước áp lực của tập thể.' WHERE ma_sach = 'S006' AND ten_sach = '1984' AND (mo_ta = 'Tiểu thuyết phản địa đàng về giám sát, tuyên truyền và quyền lực toàn trị.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Tiểu thuyết trưởng thành xoay quanh ký ức, tình yêu và mất mát của những người trẻ tại Nhật Bản. Từ những hồi tưởng của Toru Watanabe, câu chuyện mở ra các mối quan hệ phức tạp và sự bối rối khi bước vào tuổi trưởng thành. Giọng văn trầm lắng hướng đến độc giả yêu thích tiểu thuyết tâm lý, với các chủ đề nhạy cảm về mất mát và sức khỏe tinh thần.' WHERE ma_sach = 'S007' AND ten_sach = 'Norwegian Wood' AND (mo_ta = 'Tiểu thuyết trưởng thành xoay quanh ký ức, tình yêu và mất mát của những người trẻ tại Nhật Bản.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Tác phẩm văn học về công lý, định kiến và lòng trắc ẩn qua góc nhìn của một đứa trẻ. Qua lời kể của Scout và hình ảnh người cha Atticus Finch, câu chuyện đưa người đọc đến một cộng đồng miền Nam nước Mỹ với nhiều bất công và định kiến. Tác phẩm khơi gợi suy nghĩ về lòng can đảm, cách lắng nghe người khác và trách nhiệm bảo vệ điều đúng đắn.' WHERE ma_sach = 'S008' AND ten_sach = 'To Kill a Mockingbird' AND (mo_ta = 'Tác phẩm văn học về công lý, định kiến và lòng trắc ẩn qua góc nhìn của một đứa trẻ.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Phương pháp xây dựng doanh nghiệp bằng thử nghiệm, học hỏi có kiểm chứng và cải tiến liên tục. Các khái niệm sản phẩm khả dụng tối thiểu, vòng lặp xây dựng – đo lường – học hỏi và điều chỉnh hướng đi được trình bày trong bối cảnh khởi nghiệp. Người đọc có thể tham khảo để kiểm tra giả định về khách hàng trước khi dành nhiều nguồn lực phát triển sản phẩm.' WHERE ma_sach = 'S009' AND ten_sach = 'The Lean Startup' AND (mo_ta = 'Phương pháp xây dựng doanh nghiệp bằng thử nghiệm, học hỏi có kiểm chứng và cải tiến liên tục.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Các quan sát về đổi mới, lợi thế độc quyền và cách xây dựng doanh nghiệp tạo ra giá trị mới. Cuốn sách đặt vấn đề về việc tạo ra sản phẩm khác biệt thay vì chỉ lặp lại mô hình đã có trên thị trường. Những lập luận về công nghệ, thị trường ngách, đội ngũ và tầm nhìn dài hạn cung cấp góc nhìn để thảo luận khi phát triển ý tưởng kinh doanh.' WHERE ma_sach = 'S010' AND ten_sach = 'Zero to One' AND (mo_ta = 'Các quan sát về đổi mới, lợi thế độc quyền và cách xây dựng doanh nghiệp tạo ra giá trị mới.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Khám phá hai hệ thống tư duy và những thiên kiến ảnh hưởng đến quyết định của con người. Tác giả đối chiếu tư duy nhanh mang tính trực giác với tư duy chậm đòi hỏi sự tập trung và phân tích. Các ví dụ về phán đoán, rủi ro và cách diễn đạt thông tin giúp người đọc nhận diện giới hạn của trực giác trong đời sống và công việc.' WHERE ma_sach = 'S011' AND ten_sach = 'Thinking, Fast and Slow' AND (mo_ta = 'Khám phá hai hệ thống tư duy và những thiên kiến ảnh hưởng đến quyết định của con người.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Nghiên cứu các đặc điểm giúp một số công ty chuyển từ hoạt động tốt sang kết quả vượt trội. Các chủ đề gồm vai trò của lãnh đạo, lựa chọn con người, văn hóa kỷ luật và việc tập trung vào năng lực cốt lõi. Cuốn sách phù hợp để tham khảo và thảo luận về quản trị; các kết luận cần được cân nhắc theo hoàn cảnh của từng tổ chức.' WHERE ma_sach = 'S012' AND ten_sach = 'Good to Great' AND (mo_ta = 'Nghiên cứu các đặc điểm giúp một số công ty chuyển từ hoạt động tốt sang kết quả vượt trội.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Hướng dẫn xây dựng thói quen tốt và loại bỏ thói quen xấu thông qua những thay đổi nhỏ, có hệ thống. Nội dung tập trung vào mối quan hệ giữa tín hiệu, sự hấp dẫn, mức độ dễ thực hiện và phần thưởng của một hành vi. Người đọc có thể bắt đầu bằng việc thiết kế môi trường, giảm trở ngại và theo dõi những bước tiến nhỏ để duy trì việc học hoặc luyện tập.' WHERE ma_sach = 'S013' AND ten_sach = 'Atomic Habits' AND (mo_ta = 'Hướng dẫn xây dựng thói quen tốt và loại bỏ thói quen xấu thông qua những thay đổi nhỏ, có hệ thống.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Trình bày giá trị của khả năng tập trung sâu và cách tổ chức công việc trong môi trường nhiều xao nhãng. Tác giả phân tích sự khác nhau giữa công việc cần tập trung cao và những nhiệm vụ thường xuyên ngắt quãng sự chú ý. Các gợi ý về lịch làm việc, giới hạn xao nhãng và thời gian nghỉ giúp người đọc tự thiết kế một nhịp học tập hoặc làm việc phù hợp.' WHERE ma_sach = 'S014' AND ten_sach = 'Deep Work' AND (mo_ta = 'Trình bày giá trị của khả năng tập trung sâu và cách tổ chức công việc trong môi trường nhiều xao nhãng.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Những nguyên tắc giao tiếp, hợp tác và xây dựng quan hệ tích cực trong đời sống và công việc. Nội dung nhấn mạnh việc quan tâm đến người đối diện, biết lắng nghe, ghi nhận đóng góp và góp ý một cách tôn trọng. Các tình huống giao tiếp có thể dùng làm điểm khởi đầu để rèn kỹ năng hợp tác trong lớp học, gia đình và môi trường nghề nghiệp.' WHERE ma_sach = 'S015' AND ten_sach = 'How to Win Friends and Influence People' AND (mo_ta = 'Những nguyên tắc giao tiếp, hợp tác và xây dựng quan hệ tích cực trong đời sống và công việc.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
