UPDATE sach SET mo_ta = 'Tài liệu tự học ngữ pháp tiếng Anh dành cho người học ở trình độ sơ cấp. Nội dung giúp người mới học củng cố các mẫu câu cơ bản, động từ thông dụng và cách diễn đạt thường gặp trong giao tiếp. Có thể học theo từng chủ điểm hoặc chọn bài theo phần còn yếu để xây dựng nền tảng trước khi chuyển sang tài liệu trung cấp.' WHERE ma_sach = 'S022' AND ten_sach = 'Essential Grammar in Use' AND (mo_ta = 'Tài liệu tự học ngữ pháp tiếng Anh dành cho người học ở trình độ sơ cấp.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Giáo trình phát triển vốn từ tiếng Anh trình độ trung cấp theo chủ đề và ngữ cảnh sử dụng. Từ vựng được đặt trong những tình huống quen thuộc như học tập, công việc, quan hệ xã hội và sinh hoạt hằng ngày. Các hoạt động thực hành giúp người học chú ý đến cách kết hợp từ và vận dụng từ mới vào câu thay vì chỉ ghi nhớ nghĩa riêng lẻ.' WHERE ma_sach = 'S023' AND ten_sach = 'Oxford Word Skills Intermediate' AND (mo_ta = 'Giáo trình phát triển vốn từ tiếng Anh trình độ trung cấp theo chủ đề và ngữ cảnh sử dụng.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Từ điển tiếng Anh dành cho người học nâng cao với định nghĩa, ví dụ và hướng dẫn sử dụng từ. Người học có thể tra nghĩa, phát âm, từ loại và cách kết hợp từ để hiểu rõ hơn cách dùng trong ngữ cảnh. Đây là tài liệu tham khảo hữu ích khi đọc văn bản tiếng Anh, viết bài hoặc kiểm tra sự khác nhau giữa những từ gần nghĩa.' WHERE ma_sach = 'S024' AND ten_sach = 'Oxford Advanced Learner''s Dictionary' AND (mo_ta = 'Từ điển tiếng Anh dành cho người học nâng cao với định nghĩa, ví dụ và hướng dẫn sử dụng từ.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Giới thiệu những câu hỏi lớn về vũ trụ, thời gian, hố đen và nguồn gốc của không gian. Cuốn sách đưa người đọc tiếp cận những ý tưởng về sự giãn nở của vũ trụ, thuyết tương đối và mối quan hệ giữa không gian với thời gian. Lối trình bày hướng đến độc giả phổ thông ham tìm hiểu vật lý, dù một số phần vẫn cần đọc chậm và suy ngẫm.' WHERE ma_sach = 'S025' AND ten_sach = 'A Brief History of Time' AND (mo_ta = 'Giới thiệu những câu hỏi lớn về vũ trụ, thời gian, hố đen và nguồn gốc của không gian.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Hành trình qua lịch sử khám phá vũ trụ và mối liên hệ giữa khoa học với nền văn minh nhân loại. Tác phẩm kết nối những câu chuyện về các vì sao, hành tinh và sự sống với hành trình tìm kiếm tri thức của con người. Tinh thần tò mò và tư duy khoa học xuyên suốt giúp cuốn sách phù hợp với độc giả muốn mở rộng góc nhìn về vị trí của chúng ta trong vũ trụ.' WHERE ma_sach = 'S026' AND ten_sach = 'Cosmos' AND (mo_ta = 'Hành trình qua lịch sử khám phá vũ trụ và mối liên hệ giữa khoa học với nền văn minh nhân loại.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Trình bày cách nhìn tiến hóa lấy gene làm trung tâm và những hệ quả đối với hành vi sinh vật. Tác giả sử dụng góc nhìn của gene để giải thích chọn lọc tự nhiên và thảo luận các hiện tượng như cạnh tranh, hợp tác và quan hệ họ hàng. Cuốn sách phù hợp với người quan tâm sinh học tiến hóa và muốn phân biệt cách giải thích khoa học với cách hiểu đạo đức thông thường.' WHERE ma_sach = 'S027' AND ten_sach = 'The Selfish Gene' AND (mo_ta = 'Trình bày cách nhìn tiến hóa lấy gene làm trung tâm và những hệ quả đối với hành vi sinh vật.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Lịch sử khoa học của di truyền học cùng các câu hỏi y học và đạo đức liên quan đến gene. Các câu chuyện về phát hiện khoa học được đan xen với suy ngẫm về di truyền, bản sắc và lựa chọn của con người. Người đọc có cơ hội tìm hiểu vì sao kiến thức về gene mở ra nhiều khả năng nhưng cũng đặt ra những câu hỏi khó về trách nhiệm xã hội.' WHERE ma_sach = 'S028' AND ten_sach = 'The Gene' AND (mo_ta = 'Lịch sử khoa học của di truyền học cùng các câu hỏi y học và đạo đức liên quan đến gene.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Khái quát lịch sử loài người từ những cộng đồng săn bắt hái lượm đến xã hội hiện đại. Tác giả lần lượt bàn về những thay đổi trong nhận thức, nông nghiệp và khoa học đã tác động đến cách con người tổ chức cuộc sống. Đây là một góc nhìn tổng hợp để khơi gợi thảo luận về văn hóa, niềm tin và xã hội, phù hợp khi đọc cùng các nguồn lịch sử khác.' WHERE ma_sach = 'S029' AND ten_sach = 'Sapiens' AND (mo_ta = 'Khái quát lịch sử loài người từ những cộng đồng săn bắt hái lượm đến xã hội hiện đại.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Phân tích ảnh hưởng của địa lý, cây trồng, vật nuôi và công nghệ đối với sự phát triển của các xã hội. Cuốn sách đặt câu hỏi vì sao các xã hội có những con đường phát triển khác nhau và tìm lời giải qua điều kiện môi trường. Những lập luận về lương thực, dịch bệnh và sự lan truyền kỹ thuật giúp mở rộng thảo luận về lịch sử ở quy mô lớn.' WHERE ma_sach = 'S030' AND ten_sach = 'Guns, Germs, and Steel' AND (mo_ta = 'Phân tích ảnh hưởng của địa lý, cây trồng, vật nuôi và công nghệ đối với sự phát triển của các xã hội.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Kể lại lịch sử thế giới qua các tuyến giao thương và mạng lưới kết nối Á - Âu. Tác phẩm chuyển trọng tâm sang các vùng đất và tuyến đường nối liền phương Đông với phương Tây qua nhiều thời kỳ. Dòng chảy hàng hóa, tôn giáo, tư tưởng và quyền lực giúp người đọc hình dung lịch sử như một mạng lưới liên hệ giữa các cộng đồng.' WHERE ma_sach = 'S031' AND ten_sach = 'The Silk Roads' AND (mo_ta = 'Kể lại lịch sử thế giới qua các tuyến giao thương và mạng lưới kết nối Á - Âu.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Giải thích cách địa hình và vị trí địa lý tác động đến chiến lược của các quốc gia. Qua các khu vực trên thế giới, tác giả bàn về vai trò của núi, sông, đồng bằng, biển và tài nguyên trong các lựa chọn chiến lược. Cuốn sách cung cấp một cách tiếp cận địa chính trị để tham khảo, cần kết hợp với bối cảnh lịch sử và xã hội khi đánh giá từng trường hợp.' WHERE ma_sach = 'S032' AND ten_sach = 'Prisoners of Geography' AND (mo_ta = 'Giải thích cách địa hình và vị trí địa lý tác động đến chiến lược của các quốc gia.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Giáo trình toàn diện về thiết kế, phân tích thuật toán và các cấu trúc dữ liệu nền tảng. Nội dung bao gồm độ phức tạp, sắp xếp, cấu trúc dữ liệu, đồ thị và các phương pháp thiết kế thuật toán như chia để trị, tham lam, quy hoạch động. Phù hợp với sinh viên đã có kiến thức lập trình cơ bản và muốn rèn cách chứng minh tính đúng đắn cũng như đánh giá hiệu quả thuật toán.' WHERE ma_sach = 'S033' AND ten_sach = 'Introduction to Algorithms' AND (mo_ta = 'Giáo trình toàn diện về thiết kế, phân tích thuật toán và các cấu trúc dữ liệu nền tảng.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Giáo trình giải tích với lý thuyết, ví dụ và hệ thống bài tập dành cho bậc đại học. Người học được tiếp cận giới hạn, đạo hàm, tích phân và các ứng dụng qua cách trình bày gắn với bài toán cụ thể. Hệ thống ví dụ và bài tập phù hợp cho việc học theo môn, ôn kiến thức nền và luyện kỹ năng giải quyết vấn đề toán học.' WHERE ma_sach = 'S034' AND ten_sach = 'Calculus' AND (mo_ta = 'Giáo trình giải tích với lý thuyết, ví dụ và hệ thống bài tập dành cho bậc đại học.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Giáo trình sinh học đại cương bao quát tế bào, di truyền, tiến hóa, đa dạng sinh học và sinh thái. Các chủ đề được kết nối từ cấp độ phân tử và tế bào đến cơ thể, quần thể và hệ sinh thái. Phù hợp với sinh viên khối khoa học sự sống hoặc người muốn xây dựng nền tảng sinh học có hệ thống trước khi đi sâu vào một chuyên ngành.' WHERE ma_sach = 'S035' AND ten_sach = 'Campbell Biology' AND (mo_ta = 'Giáo trình sinh học đại cương bao quát tế bào, di truyền, tiến hóa, đa dạng sinh học và sinh thái.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Tài liệu tham khảo chuyên sâu về mô hình thống kê, học máy và khai phá dữ liệu. Cuốn sách trình bày hồi quy, phân loại, lựa chọn mô hình và nhiều phương pháp học có giám sát hoặc không giám sát dưới góc nhìn thống kê. Phù hợp với người đã có nền tảng xác suất, đại số tuyến tính và muốn hiểu cơ sở lý thuyết phía sau các mô hình dữ liệu.' WHERE ma_sach = 'S036' AND ten_sach = 'The Elements of Statistical Learning' AND (mo_ta = 'Tài liệu tham khảo chuyên sâu về mô hình thống kê, học máy và khai phá dữ liệu.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Tổng hợp nghiên cứu về vai trò của giấc ngủ đối với trí nhớ, sức khỏe và hiệu suất. Tác giả thảo luận về các giai đoạn ngủ, nhịp sinh học và mối liên hệ giữa nghỉ ngơi với hoạt động hằng ngày. Cuốn sách dành cho độc giả quan tâm khoa học giấc ngủ; những nội dung về sức khỏe nên được đọc như thông tin tham khảo thay vì chỉ dẫn điều trị cá nhân.' WHERE ma_sach = 'S037' AND ten_sach = 'Why We Sleep' AND (mo_ta = 'Tổng hợp nghiên cứu về vai trò của giấc ngủ đối với trí nhớ, sức khỏe và hiệu suất.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Khảo sát tác động của sang chấn lên cơ thể và tâm trí cùng các hướng tiếp cận phục hồi. Thông qua các câu chuyện lâm sàng và góc nhìn nghiên cứu, tác giả mô tả cách trải nghiệm sang chấn có thể ảnh hưởng đến cảm xúc, trí nhớ và phản ứng cơ thể. Tác phẩm có nội dung nhạy cảm, phù hợp để tìm hiểu và thảo luận về sức khỏe tinh thần, không thay thế hỗ trợ chuyên môn.' WHERE ma_sach = 'S038' AND ten_sach = 'The Body Keeps the Score' AND (mo_ta = 'Khảo sát tác động của sang chấn lên cơ thể và tâm trí cùng các hướng tiếp cận phục hồi.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Trình bày cách tiếp cận chủ động đối với sức khỏe lâu dài, phòng ngừa bệnh mạn tính và nâng cao chất lượng sống. Cuốn sách bàn về việc duy trì khả năng vận động, chú ý đến dinh dưỡng, giấc ngủ và sức khỏe cảm xúc khi tuổi tác tăng lên. Những phân tích về nguy cơ và phòng ngừa cung cấp chủ đề để người đọc trao đổi với chuyên gia y tế theo hoàn cảnh riêng.' WHERE ma_sach = 'S039' AND ten_sach = 'Outlive' AND (mo_ta = 'Trình bày cách tiếp cận chủ động đối với sức khỏe lâu dài, phòng ngừa bệnh mạn tính và nâng cao chất lượng sống.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Phương pháp sắp xếp không gian sống dựa trên việc giữ lại những đồ vật thực sự có ý nghĩa. Tác giả đề xuất sắp xếp đồ đạc theo nhóm và cân nhắc cảm nhận của bản thân khi quyết định giữ lại hay cho đi. Những gợi ý về quần áo, sách vở và vật dụng cá nhân giúp người đọc từng bước tổ chức không gian sống theo nhu cầu của mình.' WHERE ma_sach = 'S040' AND ten_sach = 'The Life-Changing Magic of Tidying Up' AND (mo_ta = 'Phương pháp sắp xếp không gian sống dựa trên việc giữ lại những đồ vật thực sự có ý nghĩa.' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
